package secrets

import (
	"os"
	"reflect"
	"regexp"
	"strings"
	"testing"

	"sigs.k8s.io/yaml"
)

// crdPath is the ManagedSecret CRD generated by the operator in this repo. MANAGEDSECRET_CRD
// overrides it (to check a CRD from another branch).
func crdPath() string {
	if p := os.Getenv("MANAGEDSECRET_CRD"); p != "" {
		return p
	}
	return "../../../operator/config/crd/bases/idp.ithaca-idp.com_managedsecrets.yaml"
}

var quoted = regexp.MustCompile(`'([^']*)'`)

// TestReservedNamesMatchTheCRD fails when the API's name rules drift from the CRD's
// x-kubernetes-validations, which would let the API accept a name the cluster rejects.
func TestReservedNamesMatchTheCRD(t *testing.T) {
	raw, err := os.ReadFile(crdPath())
	if os.IsNotExist(err) {
		t.Skipf("ManagedSecret CRD not present at %s (the operator change is on another branch)", crdPath())
	}
	if err != nil {
		t.Fatal(err)
	}
	var crd struct {
		Spec struct {
			Versions []struct {
				Schema struct {
					OpenAPIV3Schema struct {
						Validations []struct {
							Rule    string `json:"rule"`
							Message string `json:"message"`
						} `json:"x-kubernetes-validations"`
					} `json:"openAPIV3Schema"`
				} `json:"schema"`
			} `json:"versions"`
		} `json:"spec"`
	}
	if err := yaml.Unmarshal(raw, &crd); err != nil {
		t.Fatal(err)
	}
	if len(crd.Spec.Versions) == 0 {
		t.Fatal("CRD has no versions")
	}
	var names, prefixes []string
	sawLen, sawDNS := false, false
	for _, v := range crd.Spec.Versions[0].Schema.OpenAPIV3Schema.Validations {
		r := v.Rule
		switch {
		case strings.Contains(r, "size() <= "):
			sawLen = strings.Contains(r, "size() <= 40")
		case strings.Contains(r, ".matches("):
			sawDNS = strings.Contains(r, dnsLabel.String())
		case strings.Contains(r, "startsWith"):
			in, ex, ok := strings.Cut(r, "&&")
			if !ok {
				t.Fatalf("unexpected reserved-name rule: %s", r)
			}
			for _, m := range quoted.FindAllStringSubmatch(in, -1) {
				names = append(names, m[1])
			}
			for _, m := range quoted.FindAllStringSubmatch(ex, -1) {
				prefixes = append(prefixes, m[1])
			}
		}
	}
	if !sawLen || !sawDNS || MaxNameLen != 40 {
		t.Errorf("length or DNS-label rule differs from the API (len %v, dns %v)", sawLen, sawDNS)
	}
	if !reflect.DeepEqual(names, ReservedSecretNames) {
		t.Errorf("reserved names: CRD %q, API %q", names, ReservedSecretNames)
	}
	if !reflect.DeepEqual(prefixes, ReservedSecretPrefixes) {
		t.Errorf("reserved prefixes: CRD %q, API %q", prefixes, ReservedSecretPrefixes)
	}
}
